	for (i = 0; i < MLX5E_NUM_TT; i++) {
		err = mlx5e_create_tir(priv, i);
		if (err)
			goto err_destroy_tirs;
	}

	return 0;

err_destroy_tirs:
	for (i--; i >= 0; i--)
		mlx5e_destroy_tir(priv, i);

	return err;
}

static void mlx5e_destroy_tirs(struct mlx5e_priv *priv)
{
	int i;

